import{_ as d,a as e,b as a,c as r,d as o,e as i}from"./chunks/arm_10pin_jtag_connector_pinout.5fpEPKOC.js";import{_ as l,o as h,c as s,al as n}from"./chunks/framework.7vp1BMOE.js";const w=JSON.parse('{"title":"mRo Pixhawk Flight Controller (Pixhawk 1)","description":"","frontmatter":{},"headers":[],"relativePath":"zh/flight_controller/mro_pixhawk.md","filePath":"zh/flight_controller/mro_pixhawk.md"}'),p={name:"zh/flight_controller/mro_pixhawk.md"};function c(b,t,u,m,k,f){return h(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="mro-pixhawk-flight-controller-pixhawk-1" tabindex="-1">mRo Pixhawk Flight Controller (Pixhawk 1) <a class="header-anchor" href="#mro-pixhawk-flight-controller-pixhawk-1" aria-label="Permalink to &quot;mRo Pixhawk Flight Controller (Pixhawk 1)&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 does not manufacture this (or any) autopilot. Contact the <a href="https://store.mrobotics.io/" target="_blank" rel="noreferrer">manufacturer</a> for hardware support or compliance issues.</p></div><p>The <em>mRo Pixhawk<sup>®</sup></em> is a hardware compatible version of the original <a href="./../flight_controller/pixhawk">Pixhawk 1</a>. It runs PX4 on the <a href="https://nuttx.apache.org/" target="_blank" rel="noreferrer">NuttX</a> OS.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The controller can be used as a drop-in replacement for the 3DR<sup>®</sup> <a href="./../flight_controller/pixhawk">Pixhawk 1</a>. The main difference is that it is based on the <a href="https://pixhawk.org/" target="_blank" rel="noreferrer">Pixhawk-project</a> <strong>FMUv3</strong> open hardware design, which corrects a bug that limited the original Pixhawk 1 to 1MB of flash.</p></div><p><img src="'+d+'" alt="mRo Pixhawk Image"></p><p>Assembly/setup instructions for use with PX4 are provided here: <a href="./../assembly/quick_start_pixhawk">Pixhawk Wiring Quickstart</a></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This autopilot is <a href="./../flight_controller/autopilot_pixhawk_standard">supported</a> by the PX4 maintenance and test teams.</p></div><h2 id="主要特性" tabindex="-1">主要特性 <a class="header-anchor" href="#主要特性" aria-label="Permalink to &quot;主要特性&quot;">​</a></h2><ul><li><p>微处理器：</p><ul><li>32-bit STM32F427 Cortex<sup>®</sup> M4 core with FPU</li><li>168 MHz/256 KB RAM/2 MB Flash</li><li>32 bit STM32F100 failsafe co-processor</li><li>24 MHz/8 KB RAM/64 KB Flash</li></ul></li><li><p>传感器：</p><ul><li>ST Micro L3GD20 3-axis 16-bit gyroscope</li><li>ST Micro LSM303D 3-axis 14-bit accelerometer / magnetometer</li><li>Invensense<sup>®</sup> MPU 6000 3-axis accelerometer/gyroscope</li><li>MEAS MS5611 气压计</li></ul></li><li><p>接口：</p><ul><li>5x UART (serial ports), one high-power capable, 2x with HW flow control</li><li>2x CAN</li><li>Spektrum DSM / DSM2 / DSM-X® Satellite compatible input up to DX8 (DX9 and above not supported)</li><li>Futaba<sup>®</sup> S.BUS compatible input and output</li><li>PPM sum signal</li><li>RSSI (PWM or voltage) input</li><li>I2C</li><li>SPI</li><li>3.3 and 6.6V ADC inputs</li><li>External microUSB port</li></ul></li><li><p>电源系统</p><ul><li>Ideal diode controller with automatic failover</li><li>Servo rail high-power (7 V) and high-current ready</li><li>All peripheral outputs over-current protected, all inputs ESD protected</li></ul></li><li><p>重量和尺寸:</p><ul><li>Weight: 38g (1.31oz)</li><li>Width: 50mm (1.96&quot;)</li><li>Thickness: 15.5mm (.613&quot;)</li><li>Length: 81.5mm (3.21&quot;)</li></ul></li></ul><h2 id="访问链接" tabindex="-1">访问链接 <a class="header-anchor" href="#访问链接" aria-label="Permalink to &quot;访问链接&quot;">​</a></h2><ul><li><a href="https://store.mrobotics.io/Genuine-PixHawk-1-Barebones-p/mro-pixhawk1-bb-mr.htm" target="_blank" rel="noreferrer">Bare Bones</a> - Just the board (useful as a 3DR Pixhawk replacement)</li><li><a href="https://store.mrobotics.io/Genuine-PixHawk-Flight-Controller-p/mro-pixhawk1-minkit-mr.htm" target="_blank" rel="noreferrer">mRo Pixhawk 2.4.6 Essential Kit!</a> - Everything except for telemetry radios</li><li><a href="https://store.mrobotics.io/product-p/mro-pixhawk1-fullkit-mr.htm" target="_blank" rel="noreferrer">mRo Pixhawk 2.4.6 Cool Kit! (Limited edition)</a> - Everything you need including telemetry radios</li></ul><h2 id="编译固件" tabindex="-1">编译固件 <a class="header-anchor" href="#编译固件" aria-label="Permalink to &quot;编译固件&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Most users will not need to build this firmware! It is pre-built and automatically installed by <em>QGroundControl</em> when appropriate hardware is connected.</p></div><p>To <a href="./../dev_setup/building_px4">build PX4</a> for this target:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_fmu-v3_default</span></span></code></pre></div><h2 id="debug-ports" tabindex="-1">Debug Ports <a class="header-anchor" href="#debug-ports" aria-label="Permalink to &quot;Debug Ports&quot;">​</a></h2><h3 id="console-port" tabindex="-1">Console Port <a class="header-anchor" href="#console-port" aria-label="Permalink to &quot;Console Port&quot;">​</a></h3><p>The <a href="./../debug/system_console">PX4 System Console</a> runs on the port labeled <a href="#serial-4-5-port">SERIAL4/5</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>A convenient way to connect to the console is to use a <a href="https://github.com/Zubax/bugface_bf1" target="_blank" rel="noreferrer">Zubax BugFace BF1</a>, as it comes with connectors that can be used with several different Pixhawk devices. Simply connect the 6-pos DF13 1:1 cable on the <a href="https://github.com/Zubax/bugface_bf1" target="_blank" rel="noreferrer">Zubax BugFace BF1</a> to the Pixhawk <code>SERIAL4/5</code> port.</p><p><img src="'+e+'" alt="Zubax BugFace BF1"></p></div><p>The pinout is standard serial pinout, designed to connect to a <a href="https://www.digikey.com/en/products/detail/TTL-232R-3V3/768-1015-ND/1836393" target="_blank" rel="noreferrer">3.3V FTDI</a> cable (5V tolerant).</p><table tabindex="0"><thead><tr><th>3DR Pixhawk 1</th><th></th><th>FTDI</th><th></th></tr></thead><tbody><tr><td>1</td><td>+ 5v (红色)</td><td></td><td>N/C</td></tr><tr><td>2</td><td>S4 Tx</td><td></td><td>N/C</td></tr><tr><td>3</td><td>S4 Rx</td><td></td><td>N/C</td></tr><tr><td>4</td><td>S5 Tx</td><td>5</td><td>FTDI RX （黄色）</td></tr><tr><td>5</td><td>S5 Rx</td><td>4</td><td>FTDI TX （橙色）</td></tr><tr><td>6</td><td>GND</td><td>1</td><td>FTDI GND (黑色)</td></tr></tbody></table><p>The wiring for an FTDI cable to a 6-pos DF13 1:1 connector is shown in the figure below.</p><p><img src="'+a+'" alt="Console Connector"></p><p>The complete wiring is shown below.</p><p><img src="'+r+'" alt="Console Debug"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>For information on how to <em>use</em> the console see: <a href="./../debug/system_console">System Console</a>.</p></div><h3 id="swd-port" tabindex="-1">SWD Port <a class="header-anchor" href="#swd-port" aria-label="Permalink to &quot;SWD Port&quot;">​</a></h3><p>The <a href="./../debug/swd_debug">SWD</a> (JTAG) ports are hidden under the cover (which must be removed for hardware debugging). There are separate ports for FMU and IO, as highlighted below.</p><p><img src="'+o+'" alt="Pixhawk SWD"></p><p>The ports are ARM 10-pin JTAG connectors, which you will probably have to solder. The pinout for the ports is shown below (the square markers in the corners above indicates pin 1).</p><p><img src="'+i+'" alt="ARM 10-Pin connector pinout"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>All Pixhawk FMUv2 boards have a similar SWD port.</p></div><h2 id="针脚定义" tabindex="-1">针脚定义 <a class="header-anchor" href="#针脚定义" aria-label="Permalink to &quot;针脚定义&quot;">​</a></h2><h4 id="telem1-telem2-接口" tabindex="-1">TELEM1，TELEM2 接口 <a class="header-anchor" href="#telem1-telem2-接口" aria-label="Permalink to &quot;TELEM1，TELEM2 接口&quot;">​</a></h4><table tabindex="0"><thead><tr><th>针脚</th><th>信号</th><th>电压</th></tr></thead><tbody><tr><td>1（红）</td><td>VCC</td><td>+5V</td></tr><tr><td>2</td><td>TX (OUT)</td><td>+3.3V</td></tr><tr><td>3</td><td>RX (IN)</td><td>+3.3V</td></tr><tr><td>4（黑）</td><td>CTS (IN)</td><td>+3.3V</td></tr><tr><td>6</td><td>RTS (OUT)</td><td>+3.3V</td></tr><tr><td>6</td><td>GND</td><td>GND</td></tr></tbody></table><h4 id="gps-接口" tabindex="-1">GPS 接口 <a class="header-anchor" href="#gps-接口" aria-label="Permalink to &quot;GPS 接口&quot;">​</a></h4><table tabindex="0"><thead><tr><th>针脚</th><th>信号</th><th>电压</th></tr></thead><tbody><tr><td>1（红）</td><td>VCC</td><td>+5V</td></tr><tr><td>2</td><td>TX (OUT)</td><td>+3.3V</td></tr><tr><td>3</td><td>RX (IN)</td><td>+3.3V</td></tr><tr><td>4（黑）</td><td>CAN2 TX</td><td>+3.3V</td></tr><tr><td>6</td><td>CAN2 RX</td><td>+3.3V</td></tr><tr><td>6</td><td>GND</td><td>GND</td></tr></tbody></table><h4 id="serial-4-5-port" tabindex="-1">SERIAL 4/5 port <a class="header-anchor" href="#serial-4-5-port" aria-label="Permalink to &quot;SERIAL 4/5 port&quot;">​</a></h4><p>Due to space constraints two ports are on one connector.</p><table tabindex="0"><thead><tr><th>针脚</th><th>信号</th><th>电压</th></tr></thead><tbody><tr><td>1（红）</td><td>VCC</td><td>+5V</td></tr><tr><td>2</td><td>TX (#4)</td><td>+3.3V</td></tr><tr><td>3</td><td>RX (#4)</td><td>+3.3V</td></tr><tr><td>4（黑）</td><td>TX (#5)</td><td>+3.3V</td></tr><tr><td>6</td><td>RX (#5)</td><td>+3.3V</td></tr><tr><td>6</td><td>GND</td><td>GND</td></tr></tbody></table><h4 id="adc-6-6v" tabindex="-1">ADC 6.6V <a class="header-anchor" href="#adc-6-6v" aria-label="Permalink to &quot;ADC 6.6V&quot;">​</a></h4><table tabindex="0"><thead><tr><th>针脚</th><th>信号</th><th>电压</th></tr></thead><tbody><tr><td>1（红）</td><td>VCC</td><td>+5V</td></tr><tr><td>2</td><td>ADC IN</td><td>up to +6.6V</td></tr><tr><td>3</td><td>GND</td><td>GND</td></tr></tbody></table><h4 id="adc-3-3v" tabindex="-1">ADC 3.3V <a class="header-anchor" href="#adc-3-3v" aria-label="Permalink to &quot;ADC 3.3V&quot;">​</a></h4><table tabindex="0"><thead><tr><th>针脚</th><th>信号</th><th>电压</th></tr></thead><tbody><tr><td>1（红）</td><td>VCC</td><td>+5V</td></tr><tr><td>2</td><td>ADC IN</td><td>up to +3.3V</td></tr><tr><td>3</td><td>GND</td><td>GND</td></tr><tr><td>4（黑）</td><td>ADC IN</td><td>up to +3.3V</td></tr><tr><td>6</td><td>GND</td><td>GND</td></tr></tbody></table><h4 id="i2c" tabindex="-1">I2C <a class="header-anchor" href="#i2c" aria-label="Permalink to &quot;I2C&quot;">​</a></h4><table tabindex="0"><thead><tr><th>针脚</th><th>信号</th><th>电压</th></tr></thead><tbody><tr><td>1（红）</td><td>VCC</td><td>+5V</td></tr><tr><td>2</td><td>SCL</td><td>+3.3 (pullups)</td></tr><tr><td>3</td><td>SDA</td><td>+3.3 (pullups)</td></tr><tr><td>4（黑）</td><td>GND</td><td>GND</td></tr></tbody></table><h4 id="can" tabindex="-1">CAN <a class="header-anchor" href="#can" aria-label="Permalink to &quot;CAN&quot;">​</a></h4><table tabindex="0"><thead><tr><th>针脚</th><th>信号</th><th>电压</th></tr></thead><tbody><tr><td>1（红）</td><td>VCC</td><td>+5V</td></tr><tr><td>2</td><td>CAN_H</td><td>+12V</td></tr><tr><td>3</td><td>CAN_L</td><td>+12V</td></tr><tr><td>4（黑）</td><td>GND</td><td>GND</td></tr></tbody></table><h4 id="spi" tabindex="-1">SPI <a class="header-anchor" href="#spi" aria-label="Permalink to &quot;SPI&quot;">​</a></h4><table tabindex="0"><thead><tr><th>针脚</th><th>信号</th><th>电压</th></tr></thead><tbody><tr><td>1（红）</td><td>VCC</td><td>+5V</td></tr><tr><td>2</td><td>SPI_EXT_SCK</td><td>+3.3</td></tr><tr><td>3</td><td>SPI_EXT_MISO</td><td>+3.3</td></tr><tr><td>4（黑）</td><td>SPI_EXT_MOSI</td><td>+3.3</td></tr><tr><td>6</td><td>!SPI_EXT_NSS</td><td>+3.3</td></tr><tr><td>6</td><td>!GPIO_EXT</td><td>+3.3</td></tr><tr><td>7</td><td>GND</td><td>GND</td></tr></tbody></table><h4 id="power" tabindex="-1">POWER <a class="header-anchor" href="#power" aria-label="Permalink to &quot;POWER&quot;">​</a></h4><table tabindex="0"><thead><tr><th>针脚</th><th>信号</th><th>电压</th></tr></thead><tbody><tr><td>1（红）</td><td>VCC</td><td>+5V</td></tr><tr><td>2</td><td>VCC</td><td>+5V</td></tr><tr><td>3</td><td>电流</td><td>+3.3V</td></tr><tr><td>4（黑）</td><td>电压</td><td>+3.3V</td></tr><tr><td>6</td><td>GND</td><td>GND</td></tr><tr><td>6</td><td>GND</td><td>GND</td></tr></tbody></table><h4 id="switch" tabindex="-1">SWITCH <a class="header-anchor" href="#switch" aria-label="Permalink to &quot;SWITCH&quot;">​</a></h4><table tabindex="0"><thead><tr><th>针脚</th><th>信号</th><th>电压</th></tr></thead><tbody><tr><td>1（红）</td><td>VCC</td><td>+3.3V</td></tr><tr><td>2</td><td>!IO_LED_SAFETY</td><td>GND</td></tr><tr><td>3</td><td>SAFETY</td><td>GND</td></tr></tbody></table><h2 id="串口映射" tabindex="-1">串口映射 <a class="header-anchor" href="#串口映射" aria-label="Permalink to &quot;串口映射&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UART</th><th>设备</th><th>Port</th></tr></thead><tbody><tr><td>UART1</td><td>/dev/ttyS0</td><td>IO debug</td></tr><tr><td>USART2</td><td>/dev/ttyS1</td><td>TELEM1 (流控)</td></tr><tr><td>USART3</td><td>/dev/ttyS2</td><td>TELEM2 (流控)</td></tr><tr><td>UART4</td><td></td><td></td></tr><tr><td>UART7</td><td>CONSOLE</td><td></td></tr><tr><td>UART8</td><td>SERIAL4</td><td></td></tr></tbody></table><h2 id="串口映射-1" tabindex="-1">串口映射 <a class="header-anchor" href="#串口映射-1" aria-label="Permalink to &quot;串口映射&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UART</th><th>设备</th><th>Port</th></tr></thead><tbody><tr><td>UART1</td><td>/dev/ttyS0</td><td>IO debug</td></tr><tr><td>USART2</td><td>/dev/ttyS1</td><td>TELEM1 (流控)</td></tr><tr><td>USART3</td><td>/dev/ttyS2</td><td>TELEM2 (流控)</td></tr><tr><td>UART4</td><td></td><td></td></tr><tr><td>UART7</td><td>CONSOLE</td><td></td></tr><tr><td>UART8</td><td>SERIAL4</td><td></td></tr></tbody></table><h2 id="原理图" tabindex="-1">原理图 <a class="header-anchor" href="#原理图" aria-label="Permalink to &quot;原理图&quot;">​</a></h2><p>The board is based on the <a href="https://pixhawk.org/" target="_blank" rel="noreferrer">Pixhawk-project</a> <strong>FMUv3</strong> open hardware design.</p><ul><li><a href="https://github.com/pixhawk/Hardware/raw/master/FMUv3_REV_D/Schematic%20Print/Schematic%20Prints.PDF" target="_blank" rel="noreferrer">FMUv3 schematic</a> -- Schematic and layout</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>As a CC-BY-SA 3.0 licensed Open Hardware design, all schematics and design files are <a href="https://github.com/pixhawk/Hardware" target="_blank" rel="noreferrer">available</a>.</p></div>',62)])])}const P=l(p,[["render",c]]);export{w as __pageData,P as default};
